from typing import Callable, Any, Tuple
from functools import wraps, partial
import time

def _hashable(item):
    try:
        hash(item)
        return True
    except TypeError:
        return False

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    def cacheitem(item):
        return (item, timer(), _hashable(item))

    def cachekey(key):
        return (key, _hashable(key))

    def cached(func):
        cache: dict[Tuple, Any] = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = cachekey((args, tuple(kwargs.items())))
            if key in cache:
                item, last_touched, is_hashable = cache[key]
                if timer() - last_touched < ttl or not is_hashable or not args and not kwargs:
                    return item
                elif is_hashable:
                    del cache[key]
            item = func(*args, **kwargs)
            if not maxsize or is_hashable:
                cache[key] = (item, timer(), is_hashable)
                if len(cache) > maxsize:
                    oldest_key = None
                    oldest_time = float('inf')
                    for k in cache:
                        _, last_touched, _ = cache[k]
                        if last_touched < oldest_time:
                            oldest_key = k
                            oldest_time = last_touched
                    if oldest_key:
                        del cache[oldest_key]
            return item

        return wrapper

    return cached

