def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    from collections import defaultdict, OrderedDict

    class Node:
        def __init__(self, key, value):
            self.key = key
            self.value = value
            self.freq = 1

    class LFUCache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.key_to_node = {}
            self.freq_to_nodes = defaultdict(OrderedDict)
            self.min_freq = 1

        def get(self, key):
            if key not in self.key_to_node:
                return None
            node = self.key_to_node[key]
            self._update_freq(node)
            return node.value

        def put(self, key, value):
            if key in self.key_to_node:
                node = self.key_to_node[key]
                node.value = value
                self._update_freq(node)
            else:
                if len(self.key_to_node) >= self.maxsize:
                    self._evict()
                node = Node(key, value)
                self.key_to_node[key] = node
                self.freq_to_nodes[1][key] = node
                self.min_freq = 1

        def _update_freq(self, node):
            freq = node.freq
            del self.freq_to_nodes[freq][node.key]
            if not self.freq_to_nodes[self.min_freq]:
                self.min_freq += 1

            node.freq += 1
            self.freq_to_nodes[freq + 1][node.key] = node

        def _evict(self):
            node = self.freq_to_nodes[self.min_freq].popitem(last=False)[1]
            del self.key_to_node[node.key]

    def decorator(func):
        cache = LFUCache(maxsize, typed)
        def wrapper(*args, **kwargs):
            key = (func, args, tuple(kwargs.items())) if typed else (func, args)
            return cache.get(key)
        def put_func():
            return lambda value: cache.put(key, value)
        def forget_func():
            cache._evict()
        wrapper.put = put_func
        wrapper.forget = forget_func
        wrapper.clear = cache._evict
        return _update_wrapper(wrapper, func)

    return decorator

