@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    tb = sys.exc_info()[2]
    tbinfo = traceback.extract_tb(tb)

    def format_tb(info, level):
        if level > max_level:
            return ""
        return "".join(traceback.format_list(info[-level:]))

    def format_exc(e, level=1):
        if level > max_level:
            return str(e)
        if level > max_path_level:
            return str(e)
        if isinstance(e, ImportError):
            return format_exc ImportError, level + 1
        return "%s: %s" % (e.__class__.__name__, format_tb(tbinfo, level))

    return format_exc(e)

