def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not fixity:
        raise ValueError("Fixity block cannot be empty")

    allowed_algorithms = {'md5', 'sha256'}
    for file_hash in fixity.values():
        if 'hash' not in file_hash or 'algorithm' not in file_hash:
            raise ValueError("Fixity block must contain 'hash' and 'algorithm' keys")

        if file_hash['algorithm'] not in allowed_algorithms:
            raise ValueError("Unsupported fixity algorithm: {}".format(file_hash['algorithm']))

    referenced_files = set(fixity.keys())
    if not referenced_files.issubset(manifest_files):
        raise ValueError("Reference to files not found in manifest: {}".format(referenced_files - manifest_files))

