def _explore_folder(folder):
    """ Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    datas = {}
    for root, _, files in os.walk(folder):
        for f in files:
            if f.endswith('.xml'):
                xml_name = os.path.splitext(f)[0]
                if xml_name not in datas:
                    datas[xml_name] = []
                datas[xml_name].append(os.path.join(root, f))

    return datas

