    """Call the given command(s)."""

    if verbose:
        print(f"Running command: {commands} with args: {args}")

    if hide_stderr:
        stderr = subprocess.DEVNULL
    else:
        stderr = subprocess.STDOUT

    try:
        process = subprocess.Popen([commands] + args, cwd=cwd, env=env, stderr=stderr, stdout=subprocess.PIPE)
