                parsed_config = yaml.safe_load(raw_config)
                config_dict[config_file] = parsed_config
        except (IOError, yaml.YAMLError) as e:
            log_record = logging.LogRecord('load_configurations', logging.ERROR, config_file, None, None, str(e), None)
